import { escapeHtml as esc } from './core.js';
import { THEMES, CONTEXTS, STYLES, MOODS, VOICES, TYPES, ADLIBS, detectContext } from './themes.js';
import { PRESETS, MAX_SECTIONS, displayLabel, sectionBody, serializeSections } from './studio.js';

// Distingue visuellement les backs/vocalises du texte principal, seulement à l'écran (l'export reste du texte brut).
export function highlightBacks(text){
  return text.split('\n').map(line=>{
    if(/^\[Backs\]/.test(line))return `<span class="back-line">${esc(line)}</span>`;
    const inline=line.match(/^(.*\S)(\s\([^()]*\))$/);
    if(inline)return `${esc(inline[1])}<span class="back-inline">${esc(inline[2])}</span>`;
    return esc(line);
  }).join('\n');
}

const opts=(obj,value)=>Object.entries(obj).map(([v,l])=>`<option value="${esc(v)}" ${String(value)===v?'selected':''}>${esc(l)}</option>`).join('');
export function renderStudio(data,state,{icon,btn,keyboard}){
  const c=data.config,d=data.draft,sections=d.sections||[],open=state.settingsOpen||[0];
  const select=(id,label,obj,value,extra='')=>`<div class="studio-field"><label for="${id}">${label}</label><select id="${id}" name="${id.replace('cfg-','')}" ${extra}>${opts(obj,value)}</select></div>`;
  const count=sections.filter(s=>s.type==='verse').length,choruses=sections.filter(s=>s.type==='chorus').length;
  return `<div class="page-heading studio-heading"><div><p class="eyebrow">TON ATELIER DE CHANSON · V2</p><h1 tabindex="-1">Compose chaque <em>partie.</em></h1><p class="page-intro">Couplets, refrains, voix et backs. Organise ta chanson à ta façon.</p></div></div>
  <div class="composer-layout studio-layout"><aside class="composer-settings panel studio-settings"><form id="generate-form">
    <details class="setting-group" ${open.includes(0)?'open':''}><summary><span class="step-number">01</span> Ton histoire</summary>
    ${select('cfg-theme','De quoi parle ta chanson ?',THEMES,c.theme)}
    ${select('cfg-situation','Un contexte plus précis',{general:'Vue d’ensemble',...(Object.fromEntries((CONTEXTS[c.theme]||[]).map(s=>[s.id,s.label])))},c.situation)}
    <label for="cfg-context">Ton contexte personnel <span class="optional">facultatif</span></label><textarea id="cfg-context" name="context" rows="3" maxlength="1000" placeholder="Ex. Une séparation, des messages sans réponse, des fins de mois difficiles…">${esc(c.context)}</textarea>
    <div id="context-hints">${contextHints(c)}</div><p class="control-note">Les mots-clés repérés ajoutent des vers des thèmes correspondants. Le contexte libre n’est pas interprété comme par une IA.</p></details>
    <details class="setting-group" ${open.includes(1)?'open':''}><summary><span class="step-number">02</span> Style & interprétation</summary>
    ${select('cfg-style','Style',STYLES,c.style)}${select('cfg-mood','Interprétation',MOODS,c.mood)}
    <div class="field-row">${select('cfg-scheme','Rimes',{AABB:'AABB · suivies',ABAB:'ABAB · croisées',AAAA:'AAAA · une rime',libre:'Libre'},c.scheme)}<div class="studio-field"><label for="cfg-bpm">Tempo indicatif</label><input id="cfg-bpm" name="bpm" type="number" min="40" max="220" step="1" value="${c.bpm}"><span class="control-note">BPM · repère pour jouer</span></div></div>
    <p class="control-note">Le style adapte l’intro. L’interprétation et le tempo sont des indications pour le chant.</p></details>
    <details class="setting-group" ${open.includes(2)?'open':''}><summary><span class="step-number">03</span> Voix & backs</summary>
    ${select('cfg-voice','Voix principale',Object.fromEntries(Object.entries(VOICES).filter(([v])=>v!=='inherit')),c.voice)}
    <fieldset class="adlib-picker"><legend>Vocalises à ajouter</legend>${Object.entries(ADLIBS).map(([v,l])=>`<label><input type="checkbox" name="adlib" value="${v}" ${c.adlibs.includes(v)?'checked':''}><span>${esc(l)}</span></label>`).join('')}</fieldset>
    <label for="cfg-customBack">Ton back personnalisé</label><input id="cfg-customBack" name="customBack" maxlength="80" value="${esc(c.customBack)}" placeholder="Ex. Hey lê, yarê min!">
    ${select('cfg-backsFrequency','Fréquence des backs',{off:'Aucun',light:'Légers · tous les 4 vers',regular:'Réguliers · tous les 2 vers',dense:'Intenses · à chaque vers'},c.backsFrequency)}
    ${select('cfg-backsTarget','Où les placer ?',{chorus:'Refrains, pré-refrains & outro',all:'Toutes les parties chantées',ends:'Intro & outro'},c.backsTarget)}
    ${select('cfg-backMode','Placement',{response:'Réponse des chœurs',echo:'Écho des derniers mots',inline:'En fin de ligne (entre parenthèses)'},c.backMode)}
    <p class="voice-disclaimer">${icon('music')} Indications écrites de chant. Aucune voix ni musique audio n’est générée.</p></details>
    <details class="setting-group" ${open.includes(3)?'open':''}><summary><span class="step-number">04</span> Réglages des parties</summary>
    ${select('cfg-chorusMode','Quand je génère tout',{same:'Répéter le même refrain',different:'Créer des refrains différents'},c.chorusMode)}
    <div class="field-row">${select('cfg-verseLines','Nouveau couplet',{4:'4 vers',8:'8 vers',12:'12 vers'},c.verseLines)}${select('cfg-chorusLines','Nouveau refrain',{4:'4 vers',8:'8 vers',12:'12 vers'},c.chorusLines)}</div>
    <p class="control-note">Chaque partie peut ensuite avoir sa propre longueur et sa propre voix. Les parties protégées gardent leur texte.</p></details>
    <button type="submit" class="button primary full generate-button">${icon('spark')} Générer toute la chanson</button>
    <p class="local-note">Générateur local de vers préécrits, sans abonnement. Les propositions restent à relire et peuvent se répéter.</p></form>
    <div class="reserve"><h3>Ma réserve de mots <span>${data.reserve.length}</span></h3>${data.reserve.length?`<div class="reserve-chips">${data.reserve.map(w=>`<button data-action="insert-word" data-word="${esc(w)}" lang="ku">${esc(w)} ${icon('plus')}</button>`).join('')}</div><p>Clique pour insérer dans la dernière partie sélectionnée.</p>${btn('Vider la réserve','clear-reserve',null,'text-button')}`:`<p>Retrouve des rimes et garde les mots qui t’inspirent.</p>${btn('Ouvrir le dictionnaire','go-rimes','arrow','text-button')}`}</div></aside>
    <section class="studio-workbench"><div class="panel studio-project"><div class="editor-heading"><div class="section-title"><span class="step-number pink">♫</span><h2>Ta chanson</h2></div><span id="save-status" class="save-status">Brouillon local</span></div><label class="sr-only" for="song-title">Titre de la chanson</label><input class="song-title" id="song-title" maxlength="120" placeholder="Le titre de ta chanson" value="${esc(d.title)}"><div class="project-meta"><span id="editor-stats"></span><span>${count} couplet${count>1?'s':''} · ${choruses} refrain${choruses>1?'s':''}</span></div><div class="editor-actions">${btn('Sauvegarder','save-song','book','button primary')}${btn('Copier','copy-song','copy','button secondary')}${navigator.share?btn('Partager','share-song','share','button secondary'):''}${btn('Exporter','studio-export','download','button secondary')}${state.previous?btn('Annuler','undo','back','button secondary'):''}${btn('Nouveau','new-song','plus','button ghost')}</div></div>
    <div class="studio-switch"><div class="segmented" role="group" aria-label="Mode de l’éditeur"><button data-action="studio-mode" data-mode="sections" aria-pressed="${state.studioMode!=='preview'}" class="${state.studioMode!=='preview'?'selected':''}">Éditer les parties</button><button data-action="studio-mode" data-mode="preview" aria-pressed="${state.studioMode==='preview'}" class="${state.studioMode==='preview'?'selected':''}">Aperçu complet</button></div><span>${sections.length} / ${MAX_SECTIONS} parties</span></div>
    ${state.studioMode==='preview'?`<div class="panel final-preview"><div class="preview-controls"><label for="preview-clean"><input id="preview-clean" type="checkbox" ${state.previewPlain?'checked':''}> Paroles seules, sans indications de voix ni backs automatiques</label></div><pre id="full-preview" lang="ku">${highlightBacks(serializeSections(sections,c,state.previewPlain))||'Génère ou écris ta première partie pour voir la chanson complète.'}</pre><p class="control-note">Les vocalises et indications saisies manuellement dans une partie restent dans le texte.</p></div>`:`<div class="structure-toolbar panel"><div><label for="structure-preset">Partir d’une structure</label><div class="inline-form"><select id="structure-preset">${opts(PRESETS,state.preset||'standard')}</select>${btn('Appliquer','preset',null,'button secondary')}</div></div><p>Remplace l’ordre des parties. Tu peux annuler cette action.</p></div><div id="section-list">${sections.length?sections.map((s,index)=>sectionCard(s,index,sections,c,{icon,btn,keyboard})).join(''):'<div class="empty-state"><h3>Ajoute ta première partie.</h3><p>Commence par un couplet, un refrain ou une intro.</p></div>'}</div><div class="panel add-section-bar"><label for="new-section-type">Ajouter une partie</label><div class="inline-form"><select id="new-section-type">${opts(TYPES,state.addType||'verse')}</select>${btn('Ajouter','section-add','plus','button primary',sections.length>=MAX_SECTIONS?'disabled':'')}</div><div class="quick-adds">${btn('+ Couplet','quick-add',null,'word-pill','data-type="verse"')}${btn('+ Refrain','quick-add',null,'word-pill','data-type="chorus"')}${btn('+ Backs','quick-add',null,'word-pill','data-type="backs"')}${btn('+ Pont','quick-add',null,'word-pill','data-type="bridge"')}</div></div>`}
    <p class="method-note">${icon('help')} Les modifications sont enregistrées sur cet appareil. « Sauvegarder » conserve une chanson dans ton carnet. Exporte une sauvegarde pour la transférer.</p></section></div>`;
}
export function contextHints(c){const hits=detectContext(c.context);return hits.length?`<div class="context-chips"><span>Repères utilisés</span>${hits.map(h=>`<span class="context-tag">${esc(h.label)}</span>`).join('')}</div>`:c.context.trim()?'<p class="control-note">Aucun mot-clé reconnu : le thème et le contexte sélectionnés seront utilisés.</p>':'';}
function sectionCard(s,index,sections,c,{icon,btn,keyboard}){
  const sid=esc(s.id),base=`data-id="${sid}"`,counted=!['intro','instrumental','backs','free'].includes(s.type);
  const changed=s.generatedText&&s.generatedText!==s.text;
  return `<article class="section-card panel ${s.locked?'is-locked':''}" data-section="${sid}" id="part-${sid}"><header class="part-heading"><span class="part-order">${String(index+1).padStart(2,'0')}</span><div class="part-name"><label class="sr-only" for="label-${sid}">Nom de la partie ${index+1}</label><input id="label-${sid}" data-section-field="label" data-id="${sid}" maxlength="80" placeholder="${esc(displayLabel({...s,label:''},sections))}" value="${esc(s.label)}"><span>${TYPES[s.type]}${s.locked?' · texte protégé':''}</span></div><div class="part-tools">${btn('↑','section-up',null,'part-icon',`${base} aria-label="Monter cette partie" ${index===0?'disabled':''}`)}${btn('↓','section-down',null,'part-icon',`${base} aria-label="Descendre cette partie" ${index===sections.length-1?'disabled':''}`)}${btn('', 'section-duplicate','copy','part-icon',`${base} aria-label="Dupliquer cette partie" ${sections.length>=MAX_SECTIONS?'disabled':''}`)}${btn('', 'section-delete','trash','part-icon',`${base} aria-label="Supprimer cette partie"`)}</div></header>
    <div class="part-settings"><div><label for="type-${sid}">Partie</label><select id="type-${sid}" data-section-field="type" data-id="${sid}">${opts(TYPES,s.type)}</select></div><div><label for="voice-${sid}">Voix</label><select id="voice-${sid}" data-section-field="voice" data-id="${sid}">${opts(VOICES,s.voice)}</select></div><div><label for="length-${sid}">Vers à générer</label><select id="length-${sid}" data-section-field="lineCount" data-id="${sid}" ${counted?'':'disabled'}>${opts({4:'4 vers',8:'8 vers',12:'12 vers'},s.lineCount)}</select></div><div><label for="backs-${sid}">Backs</label><select id="backs-${sid}" data-section-field="backs" data-id="${sid}">${opts({inherit:'Du projet',off:'Aucun',light:'Légers',regular:'Réguliers',dense:'Intenses'},s.backs)}</select></div></div>
    <div class="part-keyboard">${keyboard('text-'+s.id)}<label class="lock-toggle"><input type="checkbox" data-section-field="locked" data-id="${sid}" ${s.locked?'checked':''}> Protéger le texte</label></div><label class="sr-only" for="text-${sid}">Paroles de ${esc(displayLabel(s,sections))}</label><textarea class="part-text" id="text-${sid}" data-section-field="text" data-id="${sid}" lang="ku" spellcheck="false" maxlength="2000" rows="${Math.min(12,Math.max(4,s.text.split('\n').length))}" placeholder="Écris ici ou génère cette partie…">${esc(s.text)}</textarea>
    <footer class="part-footer"><span class="part-count" id="count-${sid}">${s.text.split('\n').filter(l=>l.trim()).length} lignes</span><div class="part-footer-actions">${btn('Copier','section-copy','copy','text-button',`${base}`)}${btn('Régénérer cette partie','section-generate','spark','text-button',`${base} ${s.locked?'disabled':''}`)}</div></footer>
    <details class="part-preview"><summary>Voir les voix et les backs</summary><pre id="arranged-${sid}" lang="ku">${highlightBacks(sectionBody(s,c))||'Les indications apparaîtront avec ton texte.'}</pre></details>
    ${s.translation?`<details class="part-translation"><summary>Sens français de la proposition</summary><p class="translation-warning" id="warning-${sid}" ${changed?'':'hidden'}>Ce sens correspond à la proposition initiale, avant tes modifications.</p><pre>${esc(s.translation)}</pre></details>`:''}</article>`;
}
